import { z } from 'zod'
import { workflowAgentCapabilityValues } from './workflows.js'
import { seDomainSchema } from '../configuration/se-domains.js'
import { contractVersion } from './version.js'
import { accountSchema } from './portfolio.js'
import { agentTaskPromptMaxLength } from './agent-task-limits.js'

export { contractVersion } from './version.js'
export { agentTaskPromptMaxLength } from './agent-task-limits.js'
export * from './mcp.js'
export * from './portfolio.js'
export * from './workflows.js'
export * from './meeting.js'
export * from './voice.js'
export * from './seller-dashboard.js'
export * from './stage-pipeline-review.js'
export * from './record-creation.js'
export * from './cache-sync.js'
export * from './knowledge.js'

export const dataModeSchema = z.enum(['sample', 'live'])
export const sourceStateSchema = z.enum([
  'sample',
  'live',
  'stale',
  'partial',
  'unauthorized',
  'unavailable'
])

export const sourceHealthSchema = z.object({
  source: z.enum(['msx', 'mcem', 'seismic', 'linkedin', 'dataverse-mcp', 'msx-mcp']),
  state: sourceStateSchema,
  detail: z.string().min(1),
  checkedAt: z.string().datetime()
})

export const authStatusSchema = z.object({
  state: z.enum(['ready', 'cli-missing', 'login-required', 'tenant-mismatch', 'consent-required', 'permission-missing']),
  displayName: z.string().min(1).optional(),
  userEmail: z.string().email().optional(),
  tenantName: z.string().min(1).optional(),
  detail: z.string().min(1)
})

export const desktopDataStatusSchema = z.object({
  mode: dataModeSchema,
  auth: authStatusSchema
})

export const opportunitySchema = z.object({
  id: z.string().min(1),
  accountId: z.string().min(1),
  name: z.string().min(1),
  owner: z.string().min(1).optional(),
  opportunityIntent: z.array(z.string().trim().min(1)).max(10).optional(),
  recordedStage: z.number().int().min(1).max(5),
  value: z.number().finite(),
  currency: z.string().length(3),
  closeDate: z.string().date(),
  comments: z.string().optional()
})

export const milestoneSchema = z.object({
  id: z.string().min(1),
  opportunityId: z.string().min(1),
  name: z.string().min(1),
  status: z.string().min(1),
  targetDate: z.string().date().optional(),
  estimatedMonthlyUsage: z.number().optional(),
  owner: z.string().min(1).optional(),
  commitment: z.string().min(1).optional(),
  riskDetails: z.string().optional(),
  comments: z.string().optional(),
  /**
   * Whether the signed-in user is on this milestone's team. Independent of
   * opportunity Deal Team membership and of the milestone owner. Set per-user by
   * the connector at read time; omitted means membership is unknown/not evaluated.
   */
  onMilestoneTeam: z.boolean().optional()
})

export const portfolioReadVersion = '1.0' as const
export const portfolioReadRequestSchema = z.object({
  contractVersion: z.literal(portfolioReadVersion),
  includeHidden: z.boolean().optional()
}).strict()
export const portfolioIndexSchema = z.object({
  contractVersion: z.literal(portfolioReadVersion),
  accounts: z.array(accountSchema.strict()),
  opportunities: z.array(opportunitySchema.strict())
}).strict()
export const portfolioWorkspaceRequestSchema = portfolioReadRequestSchema.extend({
  accountId: z.string().min(1).max(200).optional(),
  opportunityId: z.string().min(1).max(200).optional()
}).strict()
export const portfolioWorkspaceSchema = portfolioIndexSchema.extend({
  selectedAccountId: z.string().min(1).optional(),
  selectedOpportunityId: z.string().min(1).optional(),
  milestones: z.array(milestoneSchema.strict())
}).strict()
export type PortfolioReadRequest = z.infer<typeof portfolioReadRequestSchema>
export type PortfolioIndex = z.infer<typeof portfolioIndexSchema>
export type PortfolioWorkspaceRequest = z.infer<typeof portfolioWorkspaceRequestSchema>
export type PortfolioWorkspace = z.infer<typeof portfolioWorkspaceSchema>

export const milestoneStatusSchema = z.enum([
  'On Track',
  'At Risk',
  'Blocked',
  'Completed',
  'Cancelled',
  'Lost to Competitor',
  'Hygiene/Duplicate'
])

export const customerCommitmentSchema = z.enum(['Uncommitted', 'Committed'])

export const milestoneUpdateSchema = z.object({
  status: milestoneStatusSchema.optional(),
  riskDetails: z.string().max(30_000).optional(),
  targetDate: z.string().date().optional(),
  customerCommitment: customerCommitmentSchema.optional(),
  comments: z.string().max(30_000).optional()
}).refine((value) => Object.keys(value).length > 0, 'At least one milestone field is required.')

export const opportunityUpdateSchema = z.object({
  comments: z.string().max(30_000)
})

/**
 * Result of adding the signed-in user to a milestone team. Mirrors the
 * opportunity Deal Team join result but is scoped to a single milestone and is
 * fully independent of Deal Team membership.
 */
export const milestoneTeamJoinResultSchema = z.object({
  opportunityId: z.string().min(1),
  milestoneId: z.string().min(1),
  onMilestoneTeam: z.literal(true),
  alreadyMember: z.boolean()
}).strict()

/** Result of removing only the signed-in user from a milestone team. */
export const milestoneTeamLeaveResultSchema = z.object({
  opportunityId: z.string().min(1),
  milestoneId: z.string().min(1),
  onMilestoneTeam: z.literal(false),
  alreadyAbsent: z.boolean()
}).strict()

/** Activity priority, mapped to the Dataverse task `prioritycode` (Low 0 / Normal 1 / High 2). */
export const milestoneActivityPrioritySchema = z.enum(['Low', 'Normal', 'High'])

/**
 * Task Category option set shown on the MSX "Quick Create: Task" form. Bundled so sample mode needs
 * no network; in live mode the field + option codes are environment-configured.
 */
export const taskCategorySchema = z.enum([
  'Architecture Design Session', 'Assessment', 'Blocker Escalation', 'Briefing', 'Call Back Requested',
  'Consumption Plan', 'Cross Segment', 'Cross Workload', 'Customer Engagement', 'Demo',
  'External (Co-creation of Value)', 'Internal', 'L300+ Demo', 'Negotiate Pricing', 'New Partner Request',
  'PoC/Pilot', 'Post Sales', 'Rapid Prototyping', 'RFP/RFI', 'Solution Whiteboarding', 'Tech Support',
  'Technical Close/Win Plan', 'Technical Workshop', 'Workshop'
])

/** An Activity (Task) associated with a milestone via the activity's `regardingobjectid`. */
export const milestoneActivitySchema = z.object({
  id: z.string().min(1),
  milestoneId: z.string().min(1),
  opportunityId: z.string().min(1),
  subject: z.string().min(1),
  activityType: z.string().min(1),
  status: z.string().min(1),
  priority: milestoneActivityPrioritySchema.optional(),
  taskCategory: z.string().min(1).optional(),
  due: z.string().date().optional(),
  durationMinutes: z.number().int().positive().optional(),
  description: z.string().optional(),
  owner: z.string().min(1).optional(),
  createdBy: z.string().min(1).optional(),
  createdOn: z.string().datetime().optional()
})

/** Request to create a Task regarding a milestone (owner defaults to the signed-in user). */
export const createMilestoneActivityRequestSchema = z.object({
  subject: z.string().trim().min(1).max(200),
  taskCategory: taskCategorySchema.optional(),
  description: z.string().max(30_000).optional(),
  due: z.string().date().optional(),
  priority: milestoneActivityPrioritySchema.default('Normal'),
  durationMinutes: z.number().int().positive().max(100_000).optional()
}).strict()

/**
 * An opportunity surfaced by SE-domain discovery. It extends the base
 * opportunity with the domain it matched and whether the signed-in user is
 * already on its deal team, so a client can present a one-click join action.
 */
export const discoverableOpportunitySchema = opportunitySchema.extend({
  domain: seDomainSchema,
  accountName: z.string().min(1).optional(),
  solutionArea: z.string().min(1).optional(),
  technicalCapability: z.string().min(1).optional(),
  onDealTeam: z.boolean()
})

export const discoverySnapshotVersion = '1.0' as const
export const discoverySnapshotRequestSchema = z.object({
  contractVersion: z.literal(discoverySnapshotVersion)
}).strict()
export const discoverySnapshotSchema = z.object({
  contractVersion: z.literal(discoverySnapshotVersion),
  generatedAt: z.string().datetime(),
  accounts: z.array(accountSchema.strict()),
  portfolioOpportunities: z.array(opportunitySchema.strict()),
  opportunities: z.array(discoverableOpportunitySchema.strict()),
  milestoneTeamOpportunityIds: z.array(z.string().min(1))
}).strict()
export type DiscoverySnapshotRequest = z.infer<typeof discoverySnapshotRequestSchema>
export type DiscoverySnapshot = z.infer<typeof discoverySnapshotSchema>

export const mcemStageTransitionRequestSchema = z.object({
  contractVersion: z.literal(contractVersion),
  accountId: z.string().min(1),
  opportunityId: z.string().min(1),
  targetStage: z.number().int().min(1).max(5),
  reason: z.string().trim().min(10).max(1_000).optional()
}).strict()

export const mcemStageTransitionResultSchema = z.object({
  opportunity: opportunitySchema,
  previousStage: z.number().int().min(1).max(5),
  targetStage: z.number().int().min(1).max(5),
  disposition: z.enum(['advanced', 'override', 'recycled']),
  auditNote: z.string().min(1)
}).strict()

export const evidenceSchema = z.object({
  id: z.string().min(1),
  source: z.enum(['msx', 'mcem', 'dataverse-mcp', 'msx-mcp']),
  recordId: z.string().min(1),
  title: z.string().min(1),
  url: z.string().url().optional(),
  retrievedAt: z.string().datetime(),
  modifiedAt: z.string().datetime().optional(),
  accessContext: z.enum(['sample', 'delegated-user']),
  quality: z.enum(['authoritative', 'observed', 'stale', 'incomplete']),
  excerpt: z.string().min(1)
})

export const criterionSchema = z.object({
  id: z.string().min(1),
  label: z.string().min(1),
  status: z.enum(['met', 'partial', 'missing']),
  rationale: z.string().min(1),
  evidenceIds: z.array(z.string().min(1))
})

export const recommendationSchema = z
  .object({
    id: z.string().min(1),
    action: z.string().min(1),
    ownerRole: z.string().min(1),
    rationale: z.string().min(1),
    evidenceIds: z.array(z.string().min(1)),
    assumption: z.boolean(),
    confidence: z.enum(['high', 'medium', 'low'])
  })
  .superRefine((recommendation, context) => {
    if (recommendation.evidenceIds.length === 0 && !recommendation.assumption) {
      context.addIssue({
        code: 'custom',
        path: ['evidenceIds'],
        message: 'A recommendation must cite evidence or be labeled as an assumption.'
      })
    }
  })

export const mcemRequestSchema = z.object({
  contractVersion: z.literal(contractVersion),
  accountId: z.string().min(1),
  opportunityId: z.string().min(1),
  prompt: z.string().min(3).max(1000)
})

export const agentCapabilitySchema = z.enum(workflowAgentCapabilityValues)

export const agentTaskRequestSchema = z.object({
  contractVersion: z.literal(contractVersion),
  capability: agentCapabilitySchema,
  accountId: z.string().min(1),
  opportunityId: z.string().min(1),
  prompt: z.string().min(3).max(agentTaskPromptMaxLength)
})

export const agentTaskResponseSchema = z.object({
  contractVersion: z.literal(contractVersion),
  correlationId: z.string().uuid(),
  capability: agentCapabilitySchema,
  agentVersion: z.string().min(1),
  generatedAt: z.string().datetime(),
  mode: dataModeSchema,
  state: z.enum(['complete', 'partial', 'unauthorized']),
  content: z.string().min(1),
  sourceHealth: z.array(sourceHealthSchema).min(1)
})

export const agentTaskStreamVersion = '1.0' as const

/**
 * Progressive agent response. `context` carries an instant deterministic draft grounded in the same
 * evidence as the model call; `delta` carries model text; `complete` always carries the full authoritative
 * response; `error` ends the stream without a response.
 */
export const agentTaskStreamEventSchema = z.discriminatedUnion('type', [
  z.object({
    type: z.literal('context'),
    streamVersion: z.literal(agentTaskStreamVersion),
    capability: agentCapabilitySchema,
    instantDraft: z.string().min(1),
    sourceHealth: z.array(sourceHealthSchema).min(1)
  }).strict(),
  z.object({ type: z.literal('delta'), text: z.string().min(1) }).strict(),
  z.object({ type: z.literal('complete'), response: agentTaskResponseSchema }).strict(),
  z.object({
    type: z.literal('error'),
    code: z.enum(['failed', 'timeout', 'cancelled']),
    message: z.string().min(1).max(500)
  }).strict()
])

export const emailComposeRequestSchema = z.object({
  contractVersion: z.literal(contractVersion),
  recipients: z.array(z.string().email()).min(1).max(20),
  subject: z.string().trim().min(1).max(255),
  responseTitle: z.string().trim().min(1).max(255),
  responseMarkdown: z.string().min(1).max(200_000)
}).strict()

export const emailComposeResultSchema = z.object({
  state: z.literal('opened')
}).strict()

export const exportResponseRequestSchema = z.object({
  contractVersion: z.literal(contractVersion),
  responseTitle: z.string().trim().min(1).max(255),
  responseMarkdown: z.string().min(1).max(200_000),
  generatedAt: z.string().datetime()
}).strict()

export const exportResponseResultSchema = z.discriminatedUnion('state', [
  z.object({ state: z.literal('saved'), filePath: z.string().min(1) }).strict(),
  z.object({ state: z.literal('cancelled') }).strict()
])

export const mcemResponseSchema = z.object({
  contractVersion: z.literal(contractVersion),
  correlationId: z.string().uuid(),
  capability: z.literal('mcem-coach'),
  agentVersion: z.string().min(1),
  generatedAt: z.string().datetime(),
  mode: dataModeSchema,
  state: z.enum(['complete', 'partial', 'unauthorized']),
  summary: z.string().min(1),
  recordedStage: z.number().int().min(1).max(5),
  evidenceBasedStage: z.number().int().min(1).max(5),
  criteria: z.array(criterionSchema).min(1),
  recommendations: z.array(recommendationSchema).min(1),
  missingData: z.array(z.string().min(1)),
  evidence: z.array(evidenceSchema).min(1),
  sourceHealth: z.array(sourceHealthSchema).min(1)
})

export const feedbackSchema = z.object({
  correlationId: z.string().uuid(),
  agentVersion: z.string().min(1),
  capability: z.literal('mcem-coach'),
  category: z.enum(['useful', 'incorrect', 'missing-source', 'wrong-owner', 'other']),
  comment: z.string().max(500).optional()
})

export type Opportunity = z.infer<typeof opportunitySchema>
export type DiscoverableOpportunity = z.infer<typeof discoverableOpportunitySchema>
export type Milestone = z.infer<typeof milestoneSchema>
export type MilestoneStatus = z.infer<typeof milestoneStatusSchema>
export type CustomerCommitment = z.infer<typeof customerCommitmentSchema>
export type MilestoneUpdate = z.infer<typeof milestoneUpdateSchema>
export type MilestoneTeamJoinResult = z.infer<typeof milestoneTeamJoinResultSchema>
export type MilestoneTeamLeaveResult = z.infer<typeof milestoneTeamLeaveResultSchema>
export type MilestoneActivity = z.infer<typeof milestoneActivitySchema>
export type CreateMilestoneActivityRequest = z.infer<typeof createMilestoneActivityRequestSchema>
export type TaskCategory = z.infer<typeof taskCategorySchema>
export type MilestoneActivityPriority = z.infer<typeof milestoneActivityPrioritySchema>
export type OpportunityUpdate = z.infer<typeof opportunityUpdateSchema>
export type McemStageTransitionRequest = z.infer<typeof mcemStageTransitionRequestSchema>
export type McemStageTransitionResult = z.infer<typeof mcemStageTransitionResultSchema>
export type SourceHealth = z.infer<typeof sourceHealthSchema>
export type AuthStatus = z.infer<typeof authStatusSchema>
export type DesktopDataStatus = z.infer<typeof desktopDataStatusSchema>
export type McemRequest = z.infer<typeof mcemRequestSchema>
export type McemResponse = z.infer<typeof mcemResponseSchema>
export type AgentCapability = z.infer<typeof agentCapabilitySchema>
export type AgentTaskRequest = z.infer<typeof agentTaskRequestSchema>
export type AgentTaskResponse = z.infer<typeof agentTaskResponseSchema>
export type AgentTaskStreamEvent = z.infer<typeof agentTaskStreamEventSchema>
export type EmailComposeRequest = z.infer<typeof emailComposeRequestSchema>
export type EmailComposeResult = z.infer<typeof emailComposeResultSchema>
export type ExportResponseRequest = z.infer<typeof exportResponseRequestSchema>
export type ExportResponseResult = z.infer<typeof exportResponseResultSchema>
export type Feedback = z.infer<typeof feedbackSchema>